// slide-01.js — Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: "cover",
  index: 1,
  title: "1,001 Real-World Gen AI Use Cases from Google Cloud Customers"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.08, h: 5.625,
    fill: { color: theme.accent }, line: { width: 0 }
  });

  // Top right decorative block
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.5, y: 0, w: 2.5, h: 5.625,
    fill: { color: theme.secondary }, line: { width: 0 }
  });

  // Large number watermark
  slide.addText("1,001", {
    x: 7.4, y: 0.5, w: 2.5, h: 2.5,
    fontSize: 96, fontFace: "Georgia",
    color: theme.accent, bold: true,
    align: "center", valign: "top",
    transparency: 30
  });

  // Subtitle label — report edition
  slide.addText("GOOGLE CLOUD — OCTOBER 2025", {
    x: 0.4, y: 0.55, w: 6.8, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "left", margin: 0,
    charSpacing: 4
  });

  // Main title
  slide.addText("1,001 Real-World\nGen AI Use Cases", {
    x: 0.4, y: 1.05, w: 6.8, h: 2.0,
    fontSize: 52, fontFace: "Georgia",
    color: "FFFFFF", bold: true,
    align: "left", valign: "top"
  });

  // Subtitle
  slide.addText("From the World's Leading Organizations", {
    x: 0.4, y: 3.1, w: 6.8, h: 0.55,
    fontSize: 22, fontFace: "Calibri",
    color: theme.light, bold: false,
    align: "left", valign: "top"
  });

  // Key stats row — background pill
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.85, w: 6.8, h: 0.08,
    fill: { color: theme.accent, transparency: 60 }, line: { width: 0 }
  });

  // Stat chips
  const stats = [
    { val: "1,001", label: "Use Cases" },
    { val: "11", label: "Industries" },
    { val: "6", label: "Agent Types" },
    { val: "10×", label: "Growth in 18 Mo." }
  ];
  stats.forEach((s, i) => {
    const x = 0.4 + i * 1.75;
    slide.addText(s.val, {
      x, y: 4.0, w: 1.6, h: 0.42,
      fontSize: 22, fontFace: "Georgia",
      color: theme.accent, bold: true,
      align: "center", margin: 0
    });
    slide.addText(s.label, {
      x, y: 4.44, w: 1.6, h: 0.28,
      fontSize: 11, fontFace: "Calibri",
      color: theme.light, bold: false,
      align: "center", margin: 0
    });
  });

  // Source line
  slide.addText("Source: Google Cloud Blog • Matt Renner & Matt A.V. Chaban • April 2024 – October 2025", {
    x: 0.4, y: 5.2, w: 9.2, h: 0.28,
    fontSize: 9, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "left", margin: 0
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = {
    primary: "03045e", secondary: "0077b6", accent: "00b4d8",
    light: "90e0ef", bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

