// slide-02.js — Growth Trajectory (Timeline / Data Visualization)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: "content",
  subtype: "timeline",
  index: 2,
  title: "From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.07,
    fill: { color: theme.primary }, line: { width: 0 }
  });

  // Slide title
  slide.addText("From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months", {
    x: 0.45, y: 0.18, w: 9.1, h: 0.65,
    fontSize: 26, fontFace: "Georgia",
    color: theme.primary, bold: true,
    align: "left", fit: "shrink"
  });

  // Horizontal timeline line
  slide.addShape(pres.shapes.LINE, {
    x: 1.0, y: 3.1, w: 7.8, h: 0,
    line: { color: theme.secondary, width: 3 }
  });

  // --- Node 1: April 2024 ---
  slide.addShape(pres.shapes.OVAL, {
    x: 0.8, y: 2.85, w: 0.5, h: 0.5,
    fill: { color: theme.secondary }, line: { width: 0 }
  });

  slide.addText("APR 2024", {
    x: 0.55, y: 3.42, w: 1.0, h: 0.25,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "center", margin: 0
  });

  slide.addText("Cloud Next 24", {
    x: 0.45, y: 3.68, w: 1.2, h: 0.22,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "center", margin: 0, italic: true
  });

  // Big number for 101
  slide.addText("101", {
    x: 0.5, y: 1.45, w: 1.1, h: 0.9,
    fontSize: 64, fontFace: "Georgia",
    color: theme.secondary, bold: true,
    align: "center", margin: 0
  });
  slide.addText("use cases\nlaunched", {
    x: 0.45, y: 2.35, w: 1.2, h: 0.45,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "center", margin: 0
  });

  // Vertical connector line up to 101
  slide.addShape(pres.shapes.LINE, {
    x: 1.05, y: 2.35, w: 0, h: 0.5,
    line: { color: theme.secondary, width: 2, dashType: "sysDash" }
  });

  // --- Midpoint annotation: +400 new entries ---
  slide.addShape(pres.shapes.OVAL, {
    x: 4.75, y: 2.85, w: 0.5, h: 0.5,
    fill: { color: theme.accent }, line: { width: 0 }
  });

  slide.addText("+400 new", {
    x: 4.45, y: 3.42, w: 1.1, h: 0.22,
    fontSize: 11, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "center", margin: 0
  });
  slide.addText("entries added\nin latest update", {
    x: 4.35, y: 3.66, w: 1.3, h: 0.32,
    fontSize: 10, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "center", margin: 0, italic: true
  });

  // Arrow between nodes to suggest 10x
  slide.addText("10×", {
    x: 4.45, y: 1.4, w: 1.1, h: 0.7,
    fontSize: 48, fontFace: "Georgia",
    color: theme.accent, bold: true,
    align: "center", margin: 0
  });
  slide.addText("growth", {
    x: 4.45, y: 2.12, w: 1.1, h: 0.3,
    fontSize: 13, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "center", margin: 0
  });

  // Vertical connector
  slide.addShape(pres.shapes.LINE, {
    x: 5.0, y: 2.12, w: 0, h: 0.73,
    line: { color: theme.accent, width: 2, dashType: "sysDash" }
  });

  // --- Node 2: October 2025 ---
  slide.addShape(pres.shapes.OVAL, {
    x: 8.5, y: 2.85, w: 0.5, h: 0.5,
    fill: { color: theme.primary }, line: { width: 0 }
  });

  slide.addText("OCT 2025", {
    x: 8.25, y: 3.42, w: 1.0, h: 0.25,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: false,
    align: "center", margin: 0
  });
  slide.addText("Latest Edition", {
    x: 8.15, y: 3.68, w: 1.2, h: 0.22,
    fontSize: 10, fontFace: "Calibri",
    color: theme.primary, bold: false,
    align: "center", margin: 0, italic: true
  });

  // Big number for 1,001
  slide.addText("1,001", {
    x: 7.9, y: 1.35, w: 1.6, h: 0.9,
    fontSize: 64, fontFace: "Georgia",
    color: theme.primary, bold: true,
    align: "center", margin: 0
  });
  slide.addText("use cases\ndocumented", {
    x: 7.95, y: 2.25, w: 1.5, h: 0.45,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: false,
    align: "center", margin: 0
  });

  // Vertical connector
  slide.addShape(pres.shapes.LINE, {
    x: 8.75, y: 2.7, w: 0, h: 0.15,
    line: { color: theme.primary, width: 2, dashType: "sysDash" }
  });

  // Key insight callout box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 2.0, y: 4.38, w: 6.0, h: 0.8,
    fill: { color: theme.primary }, line: { width: 0 }
  });
  slide.addText("\"The pace is still accelerating — 400 new entries added in the October 2025 update alone,\nindicating enterprise gen AI deployment is in its early exponential phase.\"", {
    x: 2.1, y: 4.44, w: 5.8, h: 0.7,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: false,
    align: "center", valign: "middle", italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = {
    primary: "03045e", secondary: "0077b6", accent: "00b4d8",
    light: "90e0ef", bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

