// slide-03.js — Industry × Agent Taxonomy Matrix
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: "content",
  subtype: "data-visualization",
  index: 3,
  title: "11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.07,
    fill: { color: theme.primary }, line: { width: 0 }
  });

  // Slide title
  slide.addText("11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI", {
    x: 0.45, y: 0.14, w: 9.1, h: 0.55,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true,
    align: "left", fit: "shrink"
  });

  const agents = ["Customer", "Employee", "Creative", "Code", "Data", "Security"];
  const industries = [
    "Automotive & Logistics",
    "Business & Prof. Services",
    "Financial Services",
    "Healthcare & Life Sciences",
    "Hospitality & Travel",
    "Manufacturing & Electronics",
    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Retail",
    "Technology",
    "Telecommunications"
  ];

  const colStart = 2.05;
  const colW = 1.28;
  const rowStart = 0.88;
  const rowH = 0.42;
  const labelColW = 1.95;

  // Agent type header cells
  agents.forEach((agent, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: colStart + i * colW, y: rowStart, w: colW - 0.04, h: 0.38,
      fill: { color: theme.primary }, line: { width: 0 }
    });
    slide.addText(agent, {
      x: colStart + i * colW, y: rowStart, w: colW - 0.04, h: 0.38,
      fontSize: 9, fontFace: "Calibri",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });
  });

  // Industry label column header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.15, y: rowStart, w: labelColW - 0.05, h: 0.38,
    fill: { color: theme.secondary }, line: { width: 0 }
  });
  slide.addText("Industry Vertical", {
    x: 0.15, y: rowStart, w: labelColW - 0.05, h: 0.38,
    fontSize: 9, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  // Matrix: which cells are highlighted (based on source data)
  // All industries have Customer + Employee; selective for others
  const highlights = {
    0:  [0, 1, 3, 2],        // Auto & Logistics: Customer, Employee, Code, Creative
    1:  [0, 1, 3, 4],        // Business & Prof: Customer, Employee, Code, Data
    2:  [0, 1, 4, 5],        // Financial: Customer, Employee, Data, Security
    3:  [0, 1, 4, 2],        // Healthcare: Customer, Employee, Data, Creative
    4:  [0, 1, 2],            // Hospitality: Customer, Employee, Creative
    5:  [0, 1, 3, 4],        // Manufacturing: Customer, Employee, Code, Data
    6:  [0, 1, 2, 3],        // Media: Customer, Employee, Creative, Code
    7:  [0, 1, 4, 5],        // Public: Customer, Employee, Data, Security
    8:  [0, 1, 2, 4],        // Retail: Customer, Employee, Creative, Data
    9:  [0, 1, 3, 4, 5],    // Technology: all except Creative
    10: [0, 1, 3, 4]          // Telecom: Customer, Employee, Code, Data
  };

  industries.forEach((industry, row) => {
    const y = rowStart + 0.38 + 0.04 + row * rowH;
    const bg = row % 2 === 0 ? "F0F7FF" : "FFFFFF";

    // Industry label
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.15, y: y, w: labelColW - 0.05, h: rowH - 0.03,
      fill: { color: bg }, line: { color: "E0EFFF", width: 0.5 }
    });
    slide.addText(industry, {
      x: 0.2, y: y, w: labelColW - 0.15, h: rowH - 0.03,
      fontSize: 9, fontFace: "Calibri",
      color: theme.primary, bold: false,
      align: "left", valign: "middle"
    });

    // Agent cells
    agents.forEach((_, col) => {
      const cx = colStart + col * colW;
      const filled = highlights[row] && highlights[row].includes(col);
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: y, w: colW - 0.04, h: rowH - 0.03,
        fill: { color: filled ? theme.accent : bg },
        line: { color: "E0EFFF", width: 0.5 }
      });
      if (filled) {
        slide.addText("●", {
          x: cx, y: y, w: colW - 0.04, h: rowH - 0.03,
          fontSize: 10, fontFace: "Arial",
          color: "FFFFFF", bold: false,
          align: "center", valign: "middle"
        });
      }
    });
  });

  // Legend
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.15, y: 5.22, w: 0.18, h: 0.18,
    fill: { color: theme.accent }, line: { width: 0 }
  });
  slide.addText("= Active deployment documented in the report", {
    x: 0.38, y: 5.21, w: 4.5, h: 0.2,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
