const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: "content",
  subtype: "data-callout",
  index: 5,
  title: "Quantified Impact: 500% ROI, 30% Workload Reduction, 10,000 Hours Saved"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Subtle side accent
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.06, h: 5.625,
    fill: { color: theme.accent }, line: { width: 0 }
  });

  // Slide title
  slide.addText("Quantified Impact: Production-Proven ROI Across Industries", {
    x: 0.3, y: 0.15, w: 9.4, h: 0.52,
    fontSize: 24, fontFace: "Georgia",
    color: "FFFFFF", bold: true,
    align: "left", fit: "shrink"
  });

  // Subtitle label
  slide.addText("These are production results — not pilots.", {
    x: 0.3, y: 0.68, w: 9.4, h: 0.3,
    fontSize: 13, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "left", italic: true
  });

  // KPI cards — 2×2 grid
  const cards = [
    {
      stat: "500%",
      label: "Anticipated ROI",
      company: "Mercari",
      detail: "Japan's largest online marketplace anticipates 500% ROI while reducing employee workloads by 20% via AI-powered customer service.",
      col: 0, row: 0
    },
    {
      stat: "30%",
      label: "CS Workload Reduction",
      company: "LUXGEN",
      detail: "Taiwan EV brand LUXGEN cut customer service agent workload by 30% using a Vertex AI chatbot on LINE.",
      col: 1, row: 0
    },
    {
      stat: "10,000+",
      label: "Man-Hours Saved / Year",
      company: "Toyota",
      detail: "Toyota's factory AI platform on Google Cloud saves over 10,000 man-hours annually by enabling workers to build and deploy ML models.",
      col: 0, row: 1
    },
    {
      stat: "6,000+",
      label: "Headlines in 29 Hours",
      company: "PODS / Tombras",
      detail: "Gemini generated 6,000+ unique ad headlines across all 299 NYC neighborhoods in just 29 hours for the World's Smartest Billboard.",
      col: 1, row: 1
    }
  ];

  const cardW = 4.55;
  const cardH = 1.9;
  const cardPadX = 0.28;
  const startX = 0.22;
  const startY = 1.08;
  const gapX = 0.18;
  const gapY = 0.18;

  cards.forEach((card) => {
    const x = startX + card.col * (cardW + gapX);
    const y = startY + card.row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: cardH,
      fill: { color: theme.secondary }, line: { width: 0 }
    });

