      x, y, w: 0.06, h: cardH,
      fill: { color: theme.accent }, line: { width: 0 }
    });

    // Company badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x + cardW - 1.4, y: y + 0.14, w: 1.3, h: 0.28,
      fill: { color: theme.accent, transparency: 70 }, line: { width: 0 }
