      num: "01",
      headline: "Gen AI is production-ready across all 11 major industries",
      body: "1,001 documented deployments across Automotive, Financial Services, Healthcare, Retail, Technology, and more — this is no longer an emerging technology. It's operational."
    },
    {
      num: "02",
      headline: "Customer and Employee agents are the most common entry points",
      body: "Conversational customer assistants and workplace productivity tools (Gemini for Workspace) dominate early deployments. Both deliver fast time-to-value with low implementation risk."
    },
    {
      num: "03",
      headline: "Measurable ROI is achievable within months",
      body: "500% anticipated ROI (Mercari), 30% workload reduction (LUXGEN), 10,000+ man-hours saved/year (Toyota). Quantified production outcomes — not pilot projections."
    },
    {
      num: "04",
      headline: "Creative and Code agents are fast-emerging opportunities",
      body: "Virgin Voyages, PODS, and Figma show gen AI moving into multimodal creative production at scale. Renault Ampere's Gemini Code Assist points to developer productivity at enterprise scale."
    },
    {
      num: "05",
      headline: "Early movers gain compounding advantages — the pace is accelerating",
      body: "400 new use cases added in the October 2025 update alone. With 10× growth in 18 months and no signs of plateau, delayed adoption means ceding competitive ground to peers already in production."
    }
  ];

  const itemH = 0.75;
  const startY = 1.05;
  const leftW = 0.55;
  const textX = 1.1;
  const textW = 8.5;

  takeaways.forEach((item, i) => {
    const y = startY + i * (itemH + 0.08);

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.3, y: y + 0.1, w: 0.48, h: 0.48,
      fill: { color: theme.primary }, line: { width: 0 }
    });
    slide.addText(item.num, {
      x: 0.3, y: y + 0.1, w: 0.48, h: 0.48,
      fontSize: 11, fontFace: "Calibri",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Headline
    slide.addText(item.headline, {
      x: textX, y: y + 0.04, w: textW, h: 0.3,
      fontSize: 13, fontFace: "Georgia",
      color: theme.primary, bold: true,
      align: "left", valign: "top", margin: 0
    });

    // Body
    slide.addText(item.body, {
      x: textX, y: y + 0.35, w: textW, h: 0.42,
      fontSize: 10.5, fontFace: "Calibri",
      color: "444444", bold: false,
      align: "left", valign: "top", margin: 0
    });

    // Divider line (skip after last item)
    if (i < takeaways.length - 1) {
      slide.addShape(pres.shapes.LINE, {
        x: 0.3, y: y + itemH + 0.04, w: 9.4, h: 0,
        line: { color: "D0E4F7", width: 0.5 }
      });
    }
  });

  // Source footer
  slide.addText("Source: Google Cloud Blog • \"1,001 real-world gen AI use cases\" • October 2025", {
    x: 0.3, y: 5.3, w: 8.5, h: 0.2,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = {
    primary: "03045e", secondary: "0077b6", accent: "00b4d8",
    light: "90e0ef", bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

