// compile.js — Compile all slides into final PPTX
const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "1,001 Real-World Gen AI Use Cases from Google Cloud Customers";
pres.author = "Google Cloud";

// Pure Tech Blue palette — professional, futuristic, clean (AI/Cloud domain)
const theme = {
  primary:   "03045e",   // deep navy — titles, headers, primary elements
  secondary: "0077b6",   // ocean blue — secondary accents, body containers
  accent:    "00b4d8",   // sky blue — highlights, KPI numbers, callouts
  light:     "90e0ef",   // light blue — supporting text on dark backgrounds
  bg:        "caf0f8"    // very light blue — slide backgrounds
};

const slideFiles = [
  "./slide-01.js",
  "./slide-02.js",
  "./slide-03.js",
  "./slide-04.js",
  "./slide-05.js",
  "./slide-06.js",
  "./slide-07.js"
];

for (const file of slideFiles) {
  const mod = require(path.resolve(__dirname, file));
  mod.createSlide(pres, theme);
}

const outPath = path.resolve(__dirname, "output/final_deck.pptx");
pres.writeFile({ fileName: outPath }).then(() => {
  console.log("PPTX written to:", outPath);
}).catch((err) => {
  console.error("Error writing PPTX:", err);
  process.exit(1);
});

